"""Per-own-process budget for the private API fixture, not an envtest bypass.

The legacy envtest feature remains unchanged. This separate contract uses the
existing TLS private_api fixture and a reviewed explicit /proc RSS/lifetime
budget because this WSL does not expose cgroup memory.current.
"""
import json,os,pathlib,signal,threading,time
from private_api import Cluster

class Budget:
    def __init__(self):
        if os.getuid()!=1000:raise RuntimeError('student UID1000 required')
        self.started=time.monotonic();self.roots=[];self.peak=0;self.peak_detail={};self.error=None
        self.closed=threading.Event();self.thread=threading.Thread(target=self.loop,daemon=True);self.thread.start()
    def watch(self,proc,group=False):self.roots.append((proc,group))
    def descendants(self,pid):
        found={pid};todo=[pid]
        while todo:
            at=todo.pop()
            try:children=pathlib.Path('/proc/'+str(at)+'/task/'+str(at)+'/children').read_text().split()
            except FileNotFoundError:continue
            for text in children:
                child=int(text)
                if child not in found:found.add(child);todo.append(child)
        return found
    def sample(self):
        pids=set()
        for proc,_ in list(self.roots):
            if proc.poll() is None:pids.update(self.descendants(proc.pid))
        rss=0;detail={}
        for pid in pids:
            try:lines=pathlib.Path('/proc/'+str(pid)+'/status').read_text().splitlines()
            except FileNotFoundError:continue
            for line in lines:
                if line.startswith('VmRSS:'):
                    size=int(line.split()[1])*1024;rss+=size;detail[pid]=size
        if rss>self.peak:self.peak=rss;self.peak_detail=detail
        if rss>805306368:raise RuntimeError('own-process native RSS budget exceeded (768MiB)')
        if time.monotonic()-self.started>90:raise RuntimeError('own-process native lifetime budget exceeded (90s)')
    def loop(self):
        while not self.closed.wait(.04):
            try:self.sample()
            except Exception as e:
                self.error=e;self.stop_processes();return
    def stop_processes(self):
        for proc,group in reversed(list(self.roots)):
            if proc.poll() is not None:continue
            try:
                if group:os.killpg(proc.pid,signal.SIGTERM)
                else:proc.terminate()
            except ProcessLookupError:pass
        for proc,group in reversed(list(self.roots)):
            try:proc.wait(timeout=3)
            except Exception:
                try:
                    if group:os.killpg(proc.pid,signal.SIGKILL)
                    else:proc.kill()
                    proc.wait(timeout=3)
                except ProcessLookupError:pass
    def check(self):
        if self.error:raise self.error
    def close(self):
        self.closed.set();self.thread.join(timeout=1);self.stop_processes()
        print('OWN_PROCESS_BUDGET '+json.dumps({'peak_rss_bytes':self.peak,'peak_by_pid':self.peak_detail,'elapsed':round(time.monotonic()-self.started,3),'processes':[{'pid':p.pid,'command':p.args,'exit_code':p.poll()} for p,_ in self.roots]}),flush=True)
    def __enter__(self):return self
    def __exit__(self,*args):self.close()

class BoundedCluster(Cluster):
    def __init__(self):
        self.budget=Budget()
        try:super().__init__()
        except Exception:
            self.close();raise
    def spawn(self,name,args):
        proc=super().spawn(name,args);self.budget.watch(proc);return proc
    def close(self):
        self.budget.close()
        if hasattr(self,'processes'):super().close()

